from datetime import date, datetime
from decimal import Decimal, InvalidOperation
import re

_DATE_RE = re.compile(r"^\d{4}-\d{2}-\d{2}$")

def _parse_iso_strict(s):
    if not isinstance(s, str):
        raise ValueError("invalid date")
    if not _DATE_RE.match(s):
        raise ValueError("invalid date")
    try:
        return datetime.strptime(s, "%Y-%m-%d").date()
    except ValueError:
        raise ValueError("invalid date")

def _quantize_exact(amts):
    if not amts:
        return Decimal("0.00")
    exps = [d.as_tuple().exponent for d in amts]
    min_exp = min(exps)
    scaled_total = 0
    for d in amts:
        t = d.as_tuple()
        if t.digits:
            mant = int("".join(str(x) for x in t.digits))
        else:
            mant = 0
        if t.sign:
            mant = -mant
        scaled_total += mant * (10 ** (t.exponent - min_exp))
    shift = min_exp + 2
    if shift >= 0:
        quant_mant = scaled_total * (10 ** shift)
    else:
        divisor = 10 ** (-shift)
        sign_neg = scaled_total < 0
        a = -scaled_total if sign_neg else scaled_total
        q, r = divmod(a, divisor)
        twice = r * 2
        if twice < divisor:
            pass
        elif twice > divisor:
            q += 1
        else:
            if q % 2 != 0:
                q += 1
        quant_mant = -q if sign_neg else q
    if quant_mant == 0:
        return Decimal("0.00")
    sign = 0 if quant_mant > 0 else 1
    s = str(abs(quant_mant))
    return Decimal((sign, tuple(int(ch) for ch in s), -2))

def aging_buckets(invoices: list[dict], as_of: date) -> dict[str, Decimal]:
    if isinstance(as_of, datetime):
        raise ValueError("invalid as_of")
    elif isinstance(as_of, date):
        as_of_date = as_of
    elif isinstance(as_of, str):
        try:
            as_of_date = _parse_iso_strict(as_of)
        except ValueError:
            raise ValueError("invalid as_of")
    else:
        raise ValueError("invalid as_of")
    buckets = {
        "current": [],
        "1-30": [],
        "31-60": [],
        "61-90": [],
        "90+": [],
    }
    for inv in invoices:
        if not isinstance(inv, dict):
            raise ValueError("invalid invoice")
        try:
            raw_due = inv["due_date"]
        except KeyError:
            raise ValueError("missing due_date")
        try:
            raw_amt = inv["amount"]
        except KeyError:
            raise ValueError("missing amount")
        if isinstance(raw_due, datetime):
            raise ValueError("invalid due_date")
        elif isinstance(raw_due, date):
            due = raw_due
        elif isinstance(raw_due, str):
            try:
                due = _parse_iso_strict(raw_due)
            except ValueError:
                raise ValueError("invalid due_date")
        else:
            raise ValueError("invalid due_date")
        if isinstance(raw_amt, bool):
            raise ValueError("invalid amount")
        elif isinstance(raw_amt, float):
            raise ValueError("invalid amount")
        elif isinstance(raw_amt, int):
            amt = Decimal(raw_amt)
        elif isinstance(raw_amt, Decimal):
            if not raw_amt.is_finite():
                raise ValueError("invalid amount")
            amt = raw_amt
        elif isinstance(raw_amt, str):
            try:
                amt = Decimal(raw_amt)
            except (InvalidOperation, ValueError, AttributeError):
                raise ValueError("invalid amount")
            if not amt.is_finite():
                raise ValueError("invalid amount")
        else:
            raise ValueError("invalid amount")
        days_overdue = (as_of_date - due).days
        if days_overdue <= 0:
            buckets["current"].append(amt)
        elif 1 <= days_overdue <= 30:
            buckets["1-30"].append(amt)
        elif 31 <= days_overdue <= 60:
            buckets["31-60"].append(amt)
        elif 61 <= days_overdue <= 90:
            buckets["61-90"].append(amt)
        else:
            buckets["90+"].append(amt)
    return {
        "current": _quantize_exact(buckets["current"]),
        "1-30": _quantize_exact(buckets["1-30"]),
        "31-60": _quantize_exact(buckets["31-60"]),
        "61-90": _quantize_exact(buckets["61-90"]),
        "90+": _quantize_exact(buckets["90+"]),
    }
